// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.math.BigInteger;
import java.util.List;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.eclipse.rdf4j.query.algebra.evaluation.function.array.GenerateSeries;
import org.junit.jupiter.api.Test;

class TemporalExtensionRegressionTest {
	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void monthBinsRecognizeClampedCalendarBoundaries() {
		for (String[] input : List.of(
				new String[] { "2024-01-31T00:00:00Z", "P1M", "2024-02-29T00:00:00Z" },
				new String[] { "2023-01-31T00:00:00Z", "P1M", "2023-02-28T00:00:00Z" },
				new String[] { "2023-11-30T00:00:00Z", "P3M", "2024-02-29T00:00:00Z" })) {
			Literal origin = dt(input[0]);
			Literal stride = duration(input[1]);
			Literal boundary = dt(input[2]);
			assertThat(new DateAdd().evaluate(VF, origin, stride)).isEqualTo(boundary);
			assertThat(new DateBin().evaluate(VF, stride, boundary, origin)).isEqualTo(boundary);
			Literal justAfter = new DateAdd().evaluate(VF, boundary, duration("PT1S"));
			assertThat(new DateBin().evaluate(VF, stride, justAfter, origin)).isEqualTo(boundary);
			Literal justBefore = new DateAdd().evaluate(VF, boundary, duration("-PT1S"));
			assertThat(new DateBin().evaluate(VF, stride, justBefore, origin)).isEqualTo(origin);
		}
	}

	@Test
	void temporalSeriesUsesInstantsForOffsetEndpoints() {
		Literal start = dt("2024-01-01T00:00:00Z");
		assertThat(GenerateSeries.series(new GenerateSeries(), VF, start,
				dt("2023-12-31T19:00:00-05:00"), duration("PT1H"))).containsExactly(start);
		assertThat(GenerateSeries.series(new GenerateSeries(), VF, start,
				dt("2023-12-31T21:00:00-05:00"), duration("PT1H")))
						.containsExactly(start, dt("2024-01-01T01:00:00Z"), dt("2024-01-01T02:00:00Z"));
		assertThat(GenerateSeries.series(new GenerateSeries(), VF, dt("2024-01-01T02:00:00Z"),
				dt("2023-12-31T19:00:00-05:00"), duration("-PT1H")))
						.containsExactly(dt("2024-01-01T02:00:00Z"), dt("2024-01-01T01:00:00Z"), start);
	}

	@Test
	void malformedDurationsAreRejectedAcrossCallers() {
		for (String lexical : List.of("P1D1D", "P1M1Y", "P1D1M", "PT1M1H", "PT1S1M", "PT1H1H", "PT.5S")) {
			Literal duration = duration(lexical);
			assertThatThrownBy(() -> new DateAdd().evaluate(VF, dt("2024-01-01T00:00:00Z"), duration))
					.as(lexical)
					.isInstanceOf(ValueExprEvaluationException.class);
			assertThatThrownBy(() -> new GenerateSeries().evaluate(VF, dt("2024-01-01T00:00:00Z"),
					dt("2024-01-02T00:00:00Z"), duration)).as(lexical)
							.isInstanceOf(ValueExprEvaluationException.class);
		}
		assertThat(new DateAdd().evaluate(VF, dt("2024-01-01T00:00:00Z"), duration("P1Y2M3DT4H5M6.7S")))
				.isEqualTo(dt("2025-03-04T04:05:06.7Z"));
	}

	@Test
	void outOfRangeEpochsRaiseEvaluationErrors() {
		for (BigInteger seconds : List.of(new BigInteger("31556889864403200"),
				new BigInteger("-31557014167219201"))) {
			assertThatThrownBy(() -> new FromUnixtime().evaluate(VF, VF.createLiteral(seconds)))
					.isInstanceOf(ValueExprEvaluationException.class);
		}
	}

	private static Literal dt(String lexical) {
		return VF.createLiteral(lexical, CoreDatatype.XSD.DATETIME);
	}

	private static Literal duration(String lexical) {
		return VF.createLiteral(lexical, CoreDatatype.XSD.DURATION);
	}
}
